const agentOutput = $json.output || '';
const lowerOutput = agentOutput.toLowerCase();

// Detect if a draft was created based on agent response
const draftCreated = lowerOutput.includes('draft has been created') ||
  lowerOutput.includes('draft created') ||
  lowerOutput.includes('created the draft') ||
  lowerOutput.includes('draft is ready');

// Try to extract subject and recipient from the conversation
let subject = '';
let recipient = '';

const subjectMatch = agentOutput.match(/\*\*Subject:\*\*\s*(.+)/i);
if (subjectMatch) subject = subjectMatch[1].trim();

const toMatch = agentOutput.match(/\*\*To:\*\*\s*(.+)/i);
if (toMatch) recipient = toMatch[1].trim();

return {
  json: {
    timestamp: new Date().toISOString(),
    action_type: 'on_demand',
    from_email: recipient,
    subject: subject,
    category: 'user_requested',
    draft_created: draftCreated ? 'true' : 'false',
    user_confirmed: draftCreated ? 'true' : 'false'
  }
};
